update exercise_catalog set description = 'Starting position: Stand with feet shoulder-width apart and a barbell in your hands in front of your thighs. Execution: Hinge forward at the hips lowering the bar toward the ground while maintaining a straight back and slightly bent knees, then slowly return to the starting position.', primary_muscle = 'full_body', equipment = 'barbell', category = 'full body', difficulty = 'intermediate', instructions = ARRAY['Position your feet hip-width apart with the barbell over the middle of your feet','Hinge at the hips and bend your knees to grip the bar with hands just outside your legs','Keep your chest up, shoulders back, and maintain a neutral spine throughout the movement','Drive through your heels and push the floor away as you stand up, extending hips and knees together','Keep the bar close to your body as it travels up your shins and thighs','Lower the weight by pushing your hips back first, then bending your knees once the bar passes them']::text[], exercise_tips = ARRAY['Maintain a neutral spine throughout the entire movement to prevent back injury','Keep the barbell as close to your body as possible during both the lifting and lowering phases','Engage your core muscles and keep your shoulders pulled back and down','Start with lighter weight to master proper form before progressing to heavier loads','Avoid rounding your back or letting your knees cave inward during the lift']::text[], secondary_muscles = ARRAY['core','forearms','adductors','upper_back']::text[], exercise_type = ARRAY['strength','functional']::text[], has_video = true, has_video_white = true, has_video_gym = true, updated_at = now() where provider = 'your_move' and external_id = '7d31d648-432b-4edd-97bc-afc2a3e9e59a';
