update exercise_catalog set description = 'Starting position: Place a barbell on your upper back with feet wider than shoulder-width and toes slightly pointed out. Execution: Lower your body into a deep squat while keeping your back straight, then push up to return to starting position.', primary_muscle = 'quads', equipment = 'barbell', category = 'legs', difficulty = 'intermediate', instructions = ARRAY['Position the barbell securely on your upper trapezius muscles and grip it with hands slightly wider than shoulder-width','Set your feet 1.5 times shoulder-width apart with toes angled outward and engage your core','Initiate the movement by pushing your hips back while keeping your chest up and spine neutral','Descend by bending at the hips and knees simultaneously until your thighs reach parallel to the floor','Drive through your heels and push the floor away to return to the starting position','Maintain the wide stance throughout the entire movement and avoid letting knees cave inward']::text[], exercise_tips = ARRAY['Keep your knees tracking in line with your toes throughout the entire range of motion to prevent knee injury','Maintain a proud chest position and avoid rounding your back under the weight','The wider stance targets the inner quads and glutes more effectively than a traditional squat','Focus on flexibility in your hip adductors as the wide stance requires good mobility','Control the descent and avoid bouncing at the bottom of the movement']::text[], secondary_muscles = '{}'::text[], exercise_type = ARRAY['strength']::text[], has_video = true, has_video_white = false, has_video_gym = true, updated_at = now() where provider = 'your_move' and external_id = 'c8f3362d-fb00-481e-b428-e0b17f4ae681';
