update exercise_catalog set description = 'Starting position: Sit on the edge of a bench with hands gripping the edge beside your hips, fingers pointing forward, and slide your hips off the bench with legs extended forward and heels on the floor. Execution: Bend your elbows to lower your body until your upper arms are roughly parallel to the floor, then press through your palms to extend your arms and return to the starting position.', primary_muscle = 'triceps', equipment = 'bodyweight', category = 'strength', difficulty = 'beginner', instructions = ARRAY['Grip the edge of the bench with hands shoulder-width apart and slide your hips off the front of the bench.','Extend your legs out in front with heels on the floor and torso upright.','Bend your elbows to lower your body until your upper arms are parallel to the floor.','Keep your elbows pointing straight back and close to your body.','Press through your palms to straighten your arms and lift your body back up.','Repeat for the desired number of repetitions without locking out harshly.']::text[], exercise_tips = ARRAY['Keep your back close to the bench to reduce shoulder strain.','Lower only until upper arms are parallel to avoid overstressing the shoulder joint.','Keep elbows tracking backward, not flaring out to the sides.','Maintain a controlled tempo and avoid using momentum.']::text[], secondary_muscles = ARRAY['front_deltoids','pectoralis_major','core']::text[], exercise_type = ARRAY['strength','calisthenics']::text[], has_video = true, has_video_white = false, has_video_gym = true, updated_at = now() where provider = 'your_move' and external_id = '48b2c98e-b82f-49aa-b847-b871a69e1b95';
