-- Group "cable tricep pushdown": keeper 207924a2-ae75-4371-be43-49c3cc62b4e1 (Cable Tricep Pushdown), discarding 1 duplicate row(s).
update exercise_catalog set description = 'Starting position: Stand facing a high pulley with a straight bar attached to the pulley. Execution: Extend your elbows to push the bar downward while keeping your elbows fixed in place.', primary_muscle = 'triceps', equipment = 'cable', category = 'arms', difficulty = 'beginner', instructions = ARRAY['Set the cable pulley to the highest position and attach your preferred handle (straight bar, rope, or V-bar)','Stand close to the machine with feet shoulder-width apart and slight forward lean','Grip the attachment with palms facing down, keeping elbows pinned to your sides throughout the movement','Push the weight down using only your forearms until your arms are completely extended','Slowly return to starting position, stopping when your forearms are parallel to the floor','Maintain constant tension on the triceps by controlling both the downward and upward phases']::text[], exercise_tips = ARRAY['Keep your elbows stationary and pressed against your sides to isolate the triceps effectively','Use a full range of motion by fully extending at the bottom and returning to forearm-parallel position at the top','Control the weight during the eccentric (returning) phase rather than letting it snap back quickly','Start with lighter weight to master proper form before progressing to heavier loads','Avoid using momentum or swinging your body to move the weight']::text[], secondary_muscles = '{}'::text[], exercise_type = ARRAY['strength']::text[], has_video = true, has_video_white = false, has_video_gym = true, updated_at = now() where provider = 'your_move' and external_id = '207924a2-ae75-4371-be43-49c3cc62b4e1';
