-- Group "close grip lat pulldown": keeper 1e99855d-fbf5-433e-9273-6f4e318a6ffe (Close Grip Lat Pulldown), discarding 1 duplicate row(s).
update exercise_catalog set description = 'Starting position: Sit at a lat pulldown machine with a close grip and hands in a supinated grip (palms facing up). Execution: Pull the bar down to your chest while keeping your torso upright, then slowly return to starting position.', primary_muscle = 'back', equipment = 'cable', category = 'back', difficulty = 'beginner', instructions = ARRAY['Adjust the knee pad to secure your thighs and prevent your body from lifting during the movement','Grasp the bar with an overhand grip, hands positioned slightly closer than shoulder-width apart','Sit tall with your chest up, shoulders back, and core engaged throughout the exercise','Pull the bar down smoothly toward your upper chest while squeezing your shoulder blades together','Focus on driving your elbows down and back rather than just pulling with your arms','Control the weight back to the starting position, maintaining tension in your lats']::text[], exercise_tips = ARRAY['Keep your torso upright and avoid leaning back excessively to prevent lower back strain','Focus on initiating the movement with your lats rather than your biceps by thinking about pulling your elbows down','Maintain a controlled tempo, especially during the eccentric (returning) phase of the movement','Avoid pulling the bar behind your neck as this can cause shoulder impingement','Stop the bar at chest level rather than pulling it to your lap to maintain proper lat engagement']::text[], secondary_muscles = '{}'::text[], exercise_type = ARRAY['strength']::text[], has_video = true, has_video_white = false, has_video_gym = true, updated_at = now() where provider = 'your_move' and external_id = '1e99855d-fbf5-433e-9273-6f4e318a6ffe';
