-- Group "dumbbell pullover": keeper c90444fe-fd21-40d1-923f-5adba83e35bc (Dumbbell Pullover), discarding 1 duplicate row(s).
update exercise_catalog set description = 'Starting position: Lie perpendicular or lengthwise on a flat bench with your upper back supported, hips lowered, and feet planted firmly on the floor. Hold a single dumbbell overhead with both hands cupping the top plate, arms nearly straight. Execution: Keeping a slight bend in the elbows, lower the dumbbell in an arc behind your head until you feel a stretch across the chest and lats, then pull it back over your chest by contracting the lats and pecs.', primary_muscle = 'lats', equipment = 'dumbbell', category = 'strength', difficulty = 'intermediate', instructions = ARRAY['Set up on a flat bench supporting your upper back and shoulders, feet flat on the floor.','Grip one dumbbell with both hands and press it above your chest with arms nearly straight.','Slowly lower the dumbbell in an arc behind your head, maintaining a slight elbow bend.','Lower until you feel a deep stretch in the lats and chest without overextending.','Pull the dumbbell back over your chest using your lats and pecs.','Control the movement throughout and repeat for the desired reps.']::text[], exercise_tips = ARRAY['Keep the elbows slightly bent and fixed throughout the arc.','Move only at the shoulder joint, not the arms or elbows.','Avoid arching the lower back excessively; keep the core braced.','Control the eccentric to protect the shoulders.']::text[], secondary_muscles = ARRAY['triceps_long_head','core','rhomboids','lats','serratus_anterior','teres_major']::text[], exercise_type = ARRAY['strength']::text[], has_video = true, has_video_white = false, has_video_gym = true, updated_at = now() where provider = 'your_move' and external_id = 'c90444fe-fd21-40d1-923f-5adba83e35bc';
