update exercise_catalog set description = 'Starting position: Stand upright holding dumbbells at your sides with arms extended down and palms facing forward. Execution: Keep your upper arms and body stationary while flexing your wrists upward to curl the weights, then slowly lower back to the starting position.', primary_muscle = 'forearms', equipment = 'dumbbell', category = 'arms', difficulty = 'intermediate', instructions = ARRAY['Stand with feet shoulder-width apart, holding a dumbbell in each hand with arms hanging naturally at your sides','Keep your upper arms pressed against your torso and avoid swinging or using momentum','Flex your wrists upward by curling the dumbbells as high as possible while keeping your forearms stationary','Hold the contracted position briefly to maximize muscle engagement','Slowly lower the weights back to the starting position with control','Maintain proper posture throughout the movement with shoulders back and core engaged']::text[], exercise_tips = ARRAY['Keep all movement isolated to the wrists and forearms - avoid using your biceps or shoulders','Use a controlled tempo, especially on the lowering phase to maximize muscle development','Start with lighter weights as forearm muscles fatigue quickly and proper form is crucial','Maintain a firm grip on the dumbbells throughout the entire range of motion','Keep your wrists in a neutral position at the bottom to avoid hyperextension']::text[], secondary_muscles = '{}'::text[], exercise_type = ARRAY['strength']::text[], has_video = true, has_video_white = true, has_video_gym = false, updated_at = now() where provider = 'your_move' and external_id = '6891aa71-6e1f-4ea4-b9ac-f38ea207216a';
