-- Group "glute kickback": keeper 4d9ad82c-1799-4340-b973-c269c901d0e5 (Glute Kickback), discarding 1 duplicate row(s).
update exercise_catalog set description = 'Starting position: Stand tall with feet hip-width apart, knees softly bent, arms bent at the sides in a running posture. Execution: Bounce lightly on the balls of your feet while pumping the arms, maintaining a quick, rhythmic cadence to elevate the heart rate.', primary_muscle = 'cardiovascular_system', equipment = 'bodyweight', category = 'cardio', difficulty = 'beginner', instructions = ARRAY['Stand upright with feet hip-width apart and elbows bent at 90 degrees.','Push off the balls of your feet to perform small, quick bounces.','Pump your arms in a controlled running motion to keep rhythm.','Land softly through the balls of the feet and immediately rebound.','Maintain an upright torso and steady breathing throughout.']::text[], exercise_tips = ARRAY['Stay light on the balls of your feet and avoid heavy heel landings.','Keep the core engaged and torso upright to protect the lower back.','Maintain a consistent, controlled pace rather than rushing.','Keep knees soft to absorb impact and reduce joint stress.']::text[], secondary_muscles = ARRAY['gastrocnemius','soleus','tibialis_anterior','core','hip_flexors']::text[], exercise_type = ARRAY['cardio','plyometric','hiit']::text[], has_video = true, has_video_white = true, has_video_gym = false, updated_at = now() where provider = 'your_move' and external_id = '4d9ad82c-1799-4340-b973-c269c901d0e5';
