update exercise_catalog set description = 'Starting position: Sit on a leg press machine with feet on the platform and knees slightly bent. Execution: Raise the heels upward by squeezing the calves, then slowly lower to starting position.', primary_muscle = 'calves', equipment = 'machine', category = 'legs', difficulty = 'beginner', instructions = ARRAY['Adjust the leg press machine seat so your knees are at approximately 90 degrees when feet are positioned','Place only the balls of your feet on the bottom edge of the footplate with heels hanging freely','Keep your knees slightly bent and maintain this position throughout the movement','Press through the balls of your feet to raise your heels as high as possible','Hold the peak contraction briefly then slowly lower your heels below the footplate level','Maintain control throughout both the lifting and lowering phases']::text[], exercise_tips = ARRAY['Keep your knees slightly bent throughout the entire movement to maintain tension on the calves','Focus on achieving a full range of motion by getting a deep stretch at the bottom and maximum contraction at the top','Use slow, controlled movements rather than bouncing to prevent injury and maximize muscle activation','Position your feet straight ahead rather than angled to ensure balanced calf development','Start with lighter weight to master the form before progressing to heavier loads']::text[], secondary_muscles = ARRAY['gastrocnemius','soleus','peroneals']::text[], exercise_type = ARRAY['strength']::text[], has_video = true, has_video_white = false, has_video_gym = true, updated_at = now() where provider = 'your_move' and external_id = '952c06b0-359b-4e38-adfd-c352723ab865';
