update exercise_catalog set description = 'Starting position: Sit on a leg curl machine with legs extended and ankles secured under the pads. Execution: Bend the knees to bring the pads toward the glutes, then slowly lower to starting position.', primary_muscle = 'hamstrings', equipment = 'machine', category = 'legs', difficulty = 'beginner', instructions = ARRAY['Adjust the machine so your knees align with the pivot point and your back is fully supported against the pad','Position the lower pad just above your ankles and secure the thigh pad snugly against your legs','Grip the side handles and maintain an upright posture throughout the movement','Curl your heels toward your glutes by contracting your hamstrings, avoiding any jerky movements','Pause briefly when your knees reach approximately 90 degrees of flexion','Slowly return to the starting position, maintaining tension in your hamstrings throughout the eccentric phase']::text[], exercise_tips = ARRAY['Keep your core engaged and avoid arching your back during the movement','Focus on a slow, controlled eccentric portion lasting 2-3 seconds for maximum muscle development','Avoid using momentum or swinging your torso to assist the movement','Ensure full range of motion while stopping just short of complete knee extension to maintain muscle tension','Breathe out during the curling phase and breathe in during the return phase']::text[], secondary_muscles = ARRAY['calves','gastrocnemius','glutes']::text[], exercise_type = ARRAY['strength']::text[], has_video = true, has_video_white = false, has_video_gym = true, updated_at = now() where provider = 'your_move' and external_id = 'a097abc2-16ac-413a-86e4-444a7ce1fa43';
