update exercise_catalog set description = 'Starting position: Lie on your back with knees bent and feet flat on the floor, hands placed lightly behind your head or crossed over your chest. Execution: Crunch up and to one side, bringing your elbow toward the opposite knee while keeping the other shoulder blade on the ground, then lower back down with control.', primary_muscle = 'core', equipment = 'bodyweight', category = 'core', difficulty = 'intermediate', instructions = ARRAY['Lie on your back with knees bent at 90 degrees and feet flat on the floor','Place hands lightly behind your head without interlacing fingers, or cross arms over your chest','Engage your core and lift your shoulder blades slightly off the ground','Crunch up and rotate to one side, bringing your right elbow toward your left knee','Lower back down to the starting position with control','Complete all repetitions on one side before switching to the other side']::text[], exercise_tips = ARRAY['Keep your lower back pressed against the floor throughout the movement to protect your spine','Focus on rotating through your torso rather than just moving your arms','Avoid pulling on your neck with your hands - let your core muscles do the work','Exhale as you crunch up and inhale as you lower down to maintain proper breathing','Move slowly and controlled to maximize muscle engagement and prevent injury']::text[], secondary_muscles = '{}'::text[], exercise_type = ARRAY['strength','core']::text[], has_video = true, has_video_white = true, has_video_gym = false, updated_at = now() where provider = 'your_move' and external_id = '85d78505-04b8-4cf6-b277-c215eeb462a7';
