update exercise_catalog set description = 'Starting position: Begin in a plank position with hands placed directly under shoulders, body forming a straight line from head to heels, and feet hip-width apart. Execution: Hold this static position while maintaining proper alignment and engaging the core muscles throughout the duration of the exercise.', primary_muscle = 'core', equipment = 'bodyweight', category = 'core', difficulty = 'beginner', instructions = ARRAY['Place hands directly under shoulders with fingers spread wide for stability','Position feet hip-width apart with toes tucked under','Create a straight line from head to heels by engaging your core and glutes','Keep your neck in neutral position by looking down at the mat','Breathe steadily while holding the position for the desired duration','Lower to knees when you can no longer maintain proper form']::text[], exercise_tips = ARRAY['Keep hips level and avoid sagging or piking up','Engage your core muscles throughout the entire hold','Distribute weight evenly between hands to avoid wrist strain','Stop the exercise if you feel lower back pain or cannot maintain proper form','Start with shorter holds and gradually increase duration as strength improves']::text[], secondary_muscles = ARRAY['front_deltoids','triceps','serratus_anterior','lower_back']::text[], exercise_type = ARRAY['core','isometric']::text[], has_video = true, has_video_white = true, has_video_gym = true, updated_at = now() where provider = 'your_move' and external_id = '61410917-4fb1-41f8-86d5-16dc88fe380b';
