update exercise_catalog set description = 'Starting position: Begin in a plank position with hands placed slightly wider than shoulder-width apart, arms fully extended, and body forming a straight line from head to heels. Execution: Lower your body by bending your elbows until your chest nearly touches the floor, then push back up to the starting position by straightening your arms.', primary_muscle = 'chest', equipment = 'bodyweight', category = 'chest', difficulty = 'intermediate', instructions = ARRAY['Position hands flat on the floor slightly wider than shoulder-width with fingers spread for stability','Keep your core engaged and maintain a straight line from head to heels throughout the movement','Lower your body slowly and controlled until your chest is about 1-2 inches from the floor','Keep your elbows at a 45-degree angle to your body rather than flaring them straight out','Push through your palms to return to the starting position with full arm extension','Breathe in as you lower down and exhale as you push back up']::text[], exercise_tips = ARRAY['Maintain proper body alignment by keeping your head in neutral position and avoiding sagging hips or raised buttocks','Start with modified versions like knee push-ups or incline push-ups if you cannot perform full push-ups with proper form','Focus on controlled movement rather than speed to maximize muscle engagement and reduce injury risk','Stop the exercise if you experience wrist pain and consider using push-up handles or making fists instead of flat palms','Progress gradually by increasing repetitions or trying more challenging variations once you can perform 15-20 perfect push-ups']::text[], secondary_muscles = ARRAY['front_deltoids','triceps','core']::text[], exercise_type = ARRAY['strength','calisthenics']::text[], has_video = true, has_video_white = true, has_video_gym = true, updated_at = now() where provider = 'your_move' and external_id = 'b41a30a8-8a02-4101-a0a9-589efdbf786b';
