-- Group "side hurdel jumps to mountain climbers": keeper 061b3246-322a-41ed-a589-73fb9478651c (Side hurdel jumps to mountain climbers), discarding 1 duplicate row(s).
update exercise_catalog set description = 'Starting position: Begin in a high plank position with hands planted firmly on the ground, shoulders directly over wrists, and body forming a straight line from head to heels. Execution: Perform lateral jumps by bringing both feet to one side outside the hands, then jumping to the opposite side, followed by alternating mountain climber knee drives while maintaining the plank position.', primary_muscle = 'core', equipment = 'bodyweight', category = 'core', difficulty = null, instructions = ARRAY['Start in a high plank position with core engaged and shoulders stable over your wrists','Jump both feet laterally to the right side, landing outside your right hand with knees bent','Immediately jump both feet to the left side, landing outside your left hand','Return to center plank position and perform 4-6 alternating mountain climber knee drives','Keep hips level throughout the lateral jumps and avoid excessive bouncing','Complete the desired number of repetitions maintaining proper form throughout']::text[], exercise_tips = ARRAY['Maintain a strong plank position throughout the entire exercise to protect your lower back','Land softly on the balls of your feet during lateral jumps to reduce impact on joints','Keep your core tight and avoid letting hips sag or pike up during transitions','Control the mountain climber tempo to maintain proper form rather than rushing through the movement','Ensure adequate space around you before beginning as this exercise requires lateral movement']::text[], secondary_muscles = '{}'::text[], exercise_type = ARRAY['cardio','plyometric','hiit']::text[], has_video = true, has_video_white = true, has_video_gym = false, updated_at = now() where provider = 'your_move' and external_id = '061b3246-322a-41ed-a589-73fb9478651c';
