update exercise_catalog set description = 'Starting position: Position yourself in a Smith machine with one leg forward and the other back. Execution: Lower your body toward the floor by bending both knees, then push upward to return to the starting position and repeat with the other leg.', primary_muscle = 'quads', equipment = 'machine', category = 'legs', difficulty = 'beginner', instructions = ARRAY['Position the Smith machine bar at shoulder height and step under it, resting it on your upper trapezius muscles','Take a large step forward with one foot while keeping the other foot planted behind you, creating a wide stance','Engage your core and maintain an upright torso throughout the movement','Lower your body by bending both knees simultaneously until your front thigh reaches parallel to the floor','Push through your front heel to drive yourself back up to the starting position','Complete all repetitions on one leg before switching to the other side']::text[], exercise_tips = ARRAY['Keep most of your weight on your front leg while using the back leg primarily for balance and stability','Ensure your front knee tracks in line with your toes and does not cave inward during the movement','Maintain an upright torso position and avoid leaning too far forward or backward','Descend in a controlled manner and avoid bouncing at the bottom of the movement','The Smith machine provides stability but still requires proper form and core engagement']::text[], secondary_muscles = '{}'::text[], exercise_type = ARRAY['strength']::text[], has_video = true, has_video_white = false, has_video_gym = true, updated_at = now() where provider = 'your_move' and external_id = '913dc03f-d923-43c5-9e7f-461c26770ee1';
