update exercise_catalog set description = 'Starting position: Position yourself in a Smith machine with the bar resting on your upper back and feet wider than shoulder-width with toes pointed slightly outward. Execution: Lower your body into a deep squat while keeping your back straight, then push up to return to starting position.', primary_muscle = 'quads', equipment = 'machine', category = 'legs', difficulty = 'intermediate', instructions = ARRAY['Set the Smith machine bar at shoulder height and add appropriate weight plates','Position yourself under the bar with feet in a wide sumo stance, toes pointed outward','Unrack the bar by lifting slightly and rotating the hooks forward','Lower your body by sitting back into your hips while keeping your chest up and knees tracking over your toes','Descend until your thighs are parallel to the floor or as low as your mobility allows','Drive through your heels and squeeze your glutes to return to the starting position']::text[], exercise_tips = ARRAY['Keep your knees aligned with your toes throughout the entire movement to prevent knee injury','Maintain a neutral spine by keeping your chest up and avoiding excessive forward lean','Focus on pushing through your heels rather than your toes to maximize quad and glute activation','Control the descent and avoid bouncing at the bottom of the movement','Engage your core throughout the exercise to maintain stability and protect your lower back']::text[], secondary_muscles = '{}'::text[], exercise_type = ARRAY['strength']::text[], has_video = true, has_video_white = false, has_video_gym = true, updated_at = now() where provider = 'your_move' and external_id = '252e37ea-e936-42a4-ba76-d7ce35e1baa6';
